mapper.update:

UPDATE group_buy_market_better.product_sku
SET stock        = stock - #{quantity},
    locked_stock = locked_stock + #{quantity}
WHERE sku_id = #{skuId}
  AND stock >= #{quantity}
  AND status = 1


UPDATE group_buy_market_better.product_sku
SET status = #{status}
WHERE sku_id = #{skuId}


UPDATE group_buy_market_better.product_sku
SET locked_stock = locked_stock - #{quantity}
WHERE sku_id = #{skuId}


UPDATE group_buy_market_better.product_sku
SET stock = stock + #{quantity}
WHERE sku_id = #{skuId}


UPDATE group_buy_market_better.product_sku
SET stock = stock + #{quantity},
    locked_stock = locked_stock - #{quantity}
WHERE sku_id = #{skuId}
